import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.Set;

public class ImmutableCollectionsDemo {

    public static void main(String[] args) {
        // 1. Structural Immutability with List.of
        List<String> frameworkRoles = List.of("USER", "MANAGER", "ADMIN");
        System.out.println("Immutable roles: " + frameworkRoles);
        System.out.println("Implementation class: " + frameworkRoles.getClass().getSimpleName());

        try {
            frameworkRoles.add("SUPER_ADMIN");
        } catch (UnsupportedOperationException e) {
            System.out.println("Caught expected rejection: add() forbidden");
        }

        // 2. Arrays.asList vs List.of (mutation leakage)
        String[] rawArray = {"ALPHA", "BETA"};
        List<String> arrayView = Arrays.asList(rawArray);
        arrayView.set(0, "MODIFIED_ALPHA");
        System.out.println("Arrays.asList modified backing array: " + rawArray[0]);

        // 3. Null rejection policy
        try {
            List.of("VALID", null);
        } catch (NullPointerException e) {
            System.out.println("List.of rejected null element with NPE");
        }

        // 4. Duplicate rejection in Set.of
        try {
            Set.of("DUPLICATE", "UNIQUE", "DUPLICATE");
        } catch (IllegalArgumentException e) {
            System.out.println("Set.of rejected duplicate key: " + e.getMessage());
        }

        // 5. copyOf() optimization
        List<String> mutableList = new ArrayList<>(Arrays.asList("EAST", "WEST"));
        List<String> snapshot1 = List.copyOf(mutableList);
        System.out.println("Snapshot 1: " + snapshot1);
        mutableList.add("NORTH");
        System.out.println("Backing list after mutation: " + mutableList);
        System.out.println("Snapshot 1 remains untouched: " + snapshot1);

        // Invoking copyOf on already immutable list yields identical reference (O(1))
        List<String> snapshot2 = List.copyOf(snapshot1);
        System.out.println("snapshot1 == snapshot2: " + (snapshot1 == snapshot2));

        // 6. Map.of and Map.ofEntries
        Map<String, Integer> endpoints = Map.of(
            "/health", 200,
            "/api/v1", 200,
            "/auth", 401
        );
        System.out.println("Immutable endpoint map size: " + endpoints.size());
    }
}
```

