import java.util.List;

public class ImmutabilityTester {
    public static boolean isStructurallyImmutable(List<String> list) {
        if (list == null) return false;
        try {
            list.add("__probe__");
            list.remove("__probe__");
            return false;
        } catch (UnsupportedOperationException e) {
            return true;
        }
    }
}
